window.AUTH=window.AUTH||{};window.AUTH["18-1165"]={"d":"18-1165","id":"2019/18-1165","n":"Retirement Plans Committee of IBM v. Jander","briefs":[{"k":"petitioner","label":"Brief of petitioners Retirement Plans Committee of IBM, et al.","date":"2019-08-06","url":"https://www.supremecourt.gov/DocketPDF/18/18-1165/111334/20190806141909677_18-1165%20TS%20IBM%20Opening.pdf","side":"pet","n":55},{"k":"united-states","label":"Brief amicus curiae of the United States in support of neither party","date":"2019-08-13","url":"https://www.supremecourt.gov/DocketPDF/18/18-1165/112272/20190813205231660_18-1165npUnitedStates.pdf","side":"us","n":54},{"k":"respondent","label":"Brief of respondents Larry W. Jander, et al.","date":"2019-09-24","url":"https://www.supremecourt.gov/DocketPDF/18/18-1165/116789/20190924125434569_No.%2018-1165%20Brief%20for%20Respondents.pdf","side":"res","n":48},{"k":"reply","label":"Reply of petitioners Retirement Plans Committee of IBM, et al.","date":"2019-10-24","url":"https://www.supremecourt.gov/DocketPDF/18/18-1165/120109/20191024130513434_18-1165%20rb.pdf","side":"pet","n":22}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=90","tr":true,"items":[{"t":"case","label":"Amgen Inc. v. Conn. Ret. Plans & Tr. Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"sum":"The Court held that during class certification, the court does not need proof of materiality and does not have to allow the defendant to present evidence to rebut the certification.","sumSrc":"Oyez","by":{"0":"60"}},{"t":"case","label":"Amgen Inc. v. Harris","cite":"136 S. Ct. 758","y":2016,"id":"2015/15-278","sc":1,"sum":"The Court held that the court of appeals erred in failing to assess whether the complaint “plausibly alleged” a breach of the duty of prudence under the standard the Court established in Fifth Third v. Dudenhoeffer.","sumSrc":"Oyez","by":{"0":"passim","1":"4, 6, 28, 29","2":"21, 22, 23, 24, 38","3":"5"}},{"t":"case","label":"AT&T Mobility v. Concepcion","cite":"563 U.S. 333","y":2011,"id":"2010/09-893","sc":1,"sum":"The Court held the Federal Arbitration Act preempts state laws that \"stand as obstacles to the FAA's objectives.\"","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Black & Decker Disability Plan v. Nord","cite":"538 U.S. 822","y":2003,"id":"2002/02-469","sc":1,"sum":"The Court held that plan administrators are not obliged to accord special deference to the opinions of treating physicians. The Court reasoned that the Court of Appeals erroneously applied a \"treating physician rule\" because nothing in ERISA gave rise to such a rule.","sumSrc":"Oyez","by":{"0":"28","1":"18"}},{"t":"case","label":"Chao v. Merino","cite":"452 F.3d 174","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/452/174/","by":{"0":"36"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"sum":"A duty to disclose information arises if there is a relationship of trust and confidence between parties to the transaction. Chiarella had no such duty. He was not a corporate insider in the acquiring corporation and he did not receive confidential information from the target company.","sumSrc":"Oyez","by":{"0":"25, 26","1":"19, 21","3":"10"}},{"t":"case","label":"Curtiss-Wright Corp. v. Schoonejongen","cite":"514 U.S. 73","y":1995,"id":"1994/93-1935","sc":1,"sum":"Petitioner Curtiss-Wright Corp. amended its employee benefit plan to provide that the postretirement health care coverage it had maintained for many years would cease for retirees upon the termination of business operations in the facility from which they retired. In ruling for respondent retirees in their ensuing suit, the District Court found, among other things, that the new provision constituted an \"amendment\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Diduck v. Kaszycki & Sons Contractors, Inc.","cite":"874 F.2d 912","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/874/912/","by":{"0":"36"}},{"t":"case","label":"Dirks v. SEC","cite":"463 U.S. 646","y":1983,"id":"1982/82-276","sc":1,"sum":"The Court held that the duty to disclose information arises from a financial relationship with one of the parties, not just the possession of information. The Court also held that an insider is only liable for inside trading when he makes a profit on the information before disclosing.","sumSrc":"Oyez","by":{"0":"25","1":"17","3":"8"}},{"t":"case","label":"Fentress v. Exxon Mobil Corp.","cite":"304 F. Supp. 3d 569","y":2018,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/304/569/","by":{"0":"50, 54"}},{"t":"case","label":"Fifth Third Bancorp v. Dudenhoeffer","cite":"573 U.S. 409","y":2014,"id":"2013/12-751","sc":1,"op":11,"ar":4,"sum":"The Court held that a trustee of an employee stock ownership plan is subject to the same duty of prudence as the trustee of a Employee Retirement Income Security Act.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Graham v. Fearon","cite":"721 F. App’x 429","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/721/429/","by":{"0":"50, 54","3":"19"}},{"t":"case","label":"Int’l Ass’n of Heat & Frost Insulators & Asbestos Workers Local #6 Pension Fund v. Int’l Bus. Mach. Corp.","cite":"205 F. Supp. 3d 527","y":2016,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/205/527/","by":{"0":"13, 14, 59","1":"9, 10","2":"55, 56, 60, 61"}},{"t":"case","label":"Kirschbaum v. Reliant Energy, Inc.","cite":"526 F.3d 243","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/526/243/","by":{"0":"30","2":"13"}},{"t":"case","label":"Laffen v. Hewlett-Packard Co.","cite":"721 F. App’x 642","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/721/642/","by":{"0":"54"}},{"t":"case","label":"Lanfear v. Home Depot, Inc.","cite":"679 F.3d 1267","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/1267/","by":{"0":"27, 30, 32","2":"13"}},{"t":"case","label":"Loeza v. John Does 1-10","cite":"659 F. App’x 44","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/659/44/","by":{"0":"54"}},{"t":"case","label":"Martone v. Robb","cite":"902 F.3d 519","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/902/519/","ar":1,"by":{"0":"44, 49, 54","2":"passim","3":"19"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"op":1,"ar":9,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"0":"23, 24, 27, 32","1":"29","2":"40, 41, 42","3":"3"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. Morgan Stanley Inv. Mgmt., Inc.","cite":"712 F.3d 705","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/712/705/","sum":"Recognizing that “the prospect of discovery in a suit claiming breach of fiduciary duty is ominous, potentially exposing the ERISA fiduciary to probing and costly inquiries and document requests”.","sumSrc":"brief:0","by":{"0":"40","2":"44"}},{"t":"case","label":"Price v. Strianese","cite":"2017 WL 4466614","y":2017,"court":"S.D.N.Y. Oct. 4","by":{"0":"50, 54"}},{"t":"case","label":"Rinehart v. Lehman Bros. Holdings Inc.","cite":"817 F.3d 56","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/817/56/","ar":1,"by":{"0":"54","2":"35"}},{"t":"case","label":"Saumer v. Cliffs Nat. Res. Inc.","cite":"853 F.3d 855","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/855/","by":{"0":"18, 38, 44, 54","2":"24"}},{"t":"case","label":"Steinman v. Hicks","cite":"352 F.3d 1101","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/352/1101/","sum":"Explaining that “Congress, believing employees’ ownership of their employer’s stock a worthy goal, has encouraged the creation of ESOPs … by giving [them] tax breaks”.","sumSrc":"brief:0","by":{"0":"7"}},{"t":"case","label":"Sweda v. Univ. of Pa.","cite":"923 F.3d 320","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/923/320/","by":{"0":"36","2":"43"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"0":"58, 59","3":"23"}},{"t":"case","label":"United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"25","1":"16, 20","3":"8"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 25, 30","2":"54, 61"}},{"t":"case","label":"Whitley v. BP, P.L.C.","cite":"838 F.3d 523","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/523/","by":{"0":"18, 38, 44, 54","1":"24"}},{"t":"case","label":"Wilson v. Edison Int’l, Inc.","cite":"315 F. Supp. 3d 1177","y":2018,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/315/1177/","by":{"0":"50, 54"}},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","stext":{"head":"§78m. Periodical and other reports","paras":[[0,"(a) Reports by issuer of security; contents"],[0,"Every issuer of a security registered pursuant to section 78l of this title shall file with the Commission, in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security—"],[1,"(1) such information and documents (and such copies thereof) as the Commission shall require to keep reasonably current the information and documents required to be included in or filed with an application or registration statement filed pursuant to section 78l of this title, except that the Commission may not require the filing of any material contract wholly executed before July 1, 1962."],[1,"(2) such annual reports (and such copies thereof), certified if required by the rules and regulations of the Commission by independent public accountants, and such quarterly reports (and such copies thereof), as the Commission may prescribe."],[0,"Every issuer of a security registered on a national securities exchange shall also file a duplicate original of such information, documents, and reports with the exchange. In any registration statement, periodic report, or other reports to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its first registration statement that became effective under this chapter or the Securities Act of 1933 [15 U.S.C. 77a et seq.] and, with respect to any such statement or reports, an emerging growth company may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Form of report; books, records, and internal accounting; directives"],[0,"(1) The Commission may prescribe, in regard to reports made pursuant to this chapter, the form or forms in which the required information shall be set forth, the items or details to be shown in the balance sheet and the earnings statement, and the methods to be followed in the preparation of reports, in the appraisal or valuation of assets and liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the preparation, where the Commission deems it necessary or desirable, of separate and/or consolidated balance sheets or income accounts of any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer; but in the case of the reports of any person whose methods of accounting are prescribed under the provisions of any law of the United States, or any rule or regulation thereunder, the rules and regulations of the Commission with respect to reports shall not be inconsistent with the requirements imposed by such law or rule or regulation in respect of the same subject matter (except that such rules and regulations of the Commission may be inconsistent with such requirements to the extent that the Commission determines that the public interest or the protection of investors so requires)."],[0,"(2) Every issuer which has a class of securities registered pursuant to section 78l of this title and every issuer which is required to file reports pursuant to section 78o(d) of this title shall—"],[1,"(A) make and keep books, records, and accounts, which, in reasonable detail, accurately and fairly reflect the transactions and dispositions of the assets of the issuer;"],[1,"(B) devise and maintain a system of internal accounting controls sufficient to provide reasonable assurances that—"],[2,"(i) transactions are executed in accordance with management's general or specific authorization;"],[2,"(ii) transactions are recorded as necessary (I) to permit preparation of financial statements in conformity with generally accepted accounting principles or any other criteria applicable to such statements, and (II) to maintain accountability for assets;"],[2,"(iii) access to assets is permitted only in accordance with management's general or specific authorization; and"],[2,"(iv) the recorded accountability for assets is compared with the existing assets at reasonable intervals and appropriate action is taken with respect to any differences; and"],[1,"(C) notwithstanding any other provision of law, pay the allocable share of such issuer of a reasonable annual accounting support fee or fees, determined in accordance with section 7219 of this title."],[0,"(3)(A) With respect to matters concerning the national security of the United States, no duty or liability under paragraph (2) of this subsection shall be imposed upon any person acting in cooperation with the head of any Federal department or agency responsible for such matters if such act in cooperation with such head of a department or agency was done upon the specific, written directive of the head of such department or agency pursuant to Presidential authority to issue such directives. Each directive issued under this paragraph shall set forth the specific facts and circumstances with respect to which the provisions of this paragraph are to be invoked. Each such directive shall, unless renewed in writing, expire one year after the date of issuance."],[0,"(B) Each head of a Federal department or agency of the United States who issues a directive pursuant to this paragraph shall maintain a complete file of all such directives and shall, on October 1 of each year, transmit a summary of matters covered by such directives in force at any time during the previous year to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate."],[0,"(4) No criminal liability shall be imposed for failing to comply with the requirements of paragraph (2) of this subsection except as provided in paragraph (5) of this subsection."],[0,"(5) No person shall knowingly circumvent or knowingly fail to implement a system of internal accounting controls or knowingly falsify any book, record, or account described in paragraph (2)."],[0,"(6) Where an issuer which has a class of securities registered pursuant to section 78l of this title or an issuer which is required to file reports pursuant to section 78o(d) of this title holds 50 per centum or less of the voting power with respect to a domestic or foreign firm, the provisions of paragraph (2) require only that the issuer proceed in good faith to use its influence, to the extent reasonable under the issuer's circumstances, to cause such domestic or foreign firm to devise and maintain a system of internal accounting controls consistent with paragraph (2). Such circumstances include the relative degree of the issuer's ownership of the domestic or foreign firm and the laws and practices governing the business operations of the country in which such firm is located. An issuer which demonstrates good faith efforts to use such influence shall be conclusively presumed to have complied with the requirements of paragraph (2)."],[0,"(7) For the purpose of paragraph (2) of this subsection, the terms \"reasonable assurances\" and \"reasonable detail\" mean such level of detail and degree of assurance as would satisfy prudent officials in the conduct of their own affairs."],[0,"(c) Alternative reports"],[0,"If in the judgment of the Commission any report required under subsection (a) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such reports of comparable character as it may deem applicable to such class or classes of issuers."],[0,"(d) Reports by persons acquiring more than five per centum of certain classes of securities"],[0,"(1) Any person who, after acquiring directly or indirectly the beneficial ownership of any equity security of a class which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.] or any equity security issued by a Native Corporation pursuant to section 1629c(d)(6) of title 43, or otherwise becomes or is deemed to become a beneficial owner of any of the foregoing upon the purchase or sale of a security-based swap that the Commission may define by rule, and is directly or indirectly the beneficial owner of more than 5 per centum of such class shall, within ten days after such acquisition or within such shorter time as the Commission may establish by rule, file with the Commission, a statement containing such of the following information, and such additional information, as the Commission may by rules and regulations, prescribe as necessary or appropriate in the public interest or for the protection of investors—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78m?type=usc&year=mostrecent&link-type=html"},"head":"§78m. Periodical and other reports","tname":"Commerce and Trade","by":{"0":"29","1":"19"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(a)(1)","(b)"],"stext":{"head":"§78u–4. Private securities litigation","paras":[[0,"(a) Private class actions"],[0,"(1) In general"],[1,"The provisions of this subsection shall apply in each private action arising under this chapter that is brought as a plaintiff class action pursuant to the Federal Rules of Civil Procedure."],[0,"(2) Certification filed with complaint"],[0,"(A) In general"],[2,"Each plaintiff seeking to serve as a representative party on behalf of a class shall provide a sworn certification, which shall be personally signed by such plaintiff and filed with the complaint, that—"],[3,"(i) states that the plaintiff has reviewed the complaint and authorized its filing;"],[3,"(ii) states that the plaintiff did not purchase the security that is the subject of the complaint at the direction of plaintiff's counsel or in order to participate in any private action arising under this chapter;"],[3,"(iii) states that the plaintiff is willing to serve as a representative party on behalf of a class, including providing testimony at deposition and trial, if necessary;"],[3,"(iv) sets forth all of the transactions of the plaintiff in the security that is the subject of the complaint during the class period specified in the complaint;"],[3,"(v) identifies any other action under this chapter, filed during the 3-year period preceding the date on which the certification is signed by the plaintiff, in which the plaintiff has sought to serve as a representative party on behalf of a class; and"],[3,"(vi) states that the plaintiff will not accept any payment for serving as a representative party on behalf of a class beyond the plaintiff's pro rata share of any recovery, except as ordered or approved by the court in accordance with paragraph (4)."],[0,"(B) Nonwaiver of attorney-client privilege"],[2,"The certification filed pursuant to subparagraph (A) shall not be construed to be a waiver of the attorney-client privilege."],[0,"(3) Appointment of lead plaintiff"],[0,"(A) Early notice to class members"],[0,"(i) In general"],[3,"Not later than 20 days after the date on which the complaint is filed, the plaintiff or plaintiffs shall cause to be published, in a widely circulated national business-oriented publication or wire service, a notice advising members of the purported plaintiff class—"],[4,"(I) of the pendency of the action, the claims asserted therein, and the purported class period; and"],[4,"(II) that, not later than 60 days after the date on which the notice is published, any member of the purported class may move the court to serve as lead plaintiff of the purported class."],[0,"(ii) Multiple actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter is filed, only the plaintiff or plaintiffs in the first filed action shall be required to cause notice to be published in accordance with clause (i)."],[0,"(iii) Additional notices may be required under Federal rules"],[3,"Notice required under clause (i) shall be in addition to any notice required pursuant to the Federal Rules of Civil Procedure."],[0,"(B) Appointment of lead plaintiff"],[0,"(i) In general"],[3,"Not later than 90 days after the date on which a notice is published under subparagraph (A)(i), the court shall consider any motion made by a purported class member in response to the notice, including any motion by a class member who is not individually named as a plaintiff in the complaint or complaints, and shall appoint as lead plaintiff the member or members of the purported plaintiff class that the court determines to be most capable of adequately representing the interests of class members (hereafter in this paragraph referred to as the \"most adequate plaintiff\") in accordance with this subparagraph."],[0,"(ii) Consolidated actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter has been filed, and any party has sought to consolidate those actions for pretrial purposes or for trial, the court shall not make the determination required by clause (i) until after the decision on the motion to consolidate is rendered. As soon as practicable after such decision is rendered, the court shall appoint the most adequate plaintiff as lead plaintiff for the consolidated actions in accordance with this paragraph."],[0,"(iii) Rebuttable presumption"],[0,"(I) In general"],[4,"Subject to subclause (II), for purposes of clause (i), the court shall adopt a presumption that the most adequate plaintiff in any private action arising under this chapter is the person or group of persons that—"],[5,"(aa) has either filed the complaint or made a motion in response to a notice under subparagraph (A)(i);"],[5,"(bb) in the determination of the court, has the largest financial interest in the relief sought by the class; and"],[5,"(cc) otherwise satisfies the requirements of Rule 23 of the Federal Rules of Civil Procedure."],[0,"(II) Rebuttal evidence"],[4,"The presumption described in subclause (I) may be rebutted only upon proof by a member of the purported plaintiff class that the presumptively most adequate plaintiff—"],[5,"(aa) will not fairly and adequately protect the interests of the class; or"],[5,"(bb) is subject to unique defenses that render such plaintiff incapable of adequately representing the class."],[0,"(iv) Discovery"],[3,"For purposes of this subparagraph, discovery relating to whether a member or members of the purported plaintiff class is the most adequate plaintiff may be conducted by a plaintiff only if the plaintiff first demonstrates a reasonable basis for a finding that the presumptively most adequate plaintiff is incapable of adequately representing the class."],[0,"(v) Selection of lead counsel"],[3,"The most adequate plaintiff shall, subject to the approval of the court, select and retain counsel to represent the class."],[0,"(vi) Restrictions on professional plaintiffs"],[3,"Except as the court may otherwise permit, consistent with the purposes of this section, a person may be a lead plaintiff, or an officer, director, or fiduciary of a lead plaintiff, in no more than 5 securities class actions brought as plaintiff class actions pursuant to the Federal Rules of Civil Procedure during any 3-year period."],[0,"(4) Recovery by plaintiffs"],[1,"The share of any final judgment or of any settlement that is awarded to a representative party serving on behalf of a class shall be equal, on a per share basis, to the portion of the final judgment or settlement awarded to all other members of the class. Nothing in this paragraph shall be construed to limit the award of reasonable costs and expenses (including lost wages) directly relating to the representation of the class to any representative party serving on behalf of a class."],[0,"(5) Restrictions on settlements under seal"],[1,"The terms and provisions of any settlement agreement of a class action shall not be filed under seal, except that on motion of any party to the settlement, the court may order filing under seal for those portions of a settlement agreement as to which good cause is shown for such filing under seal. For purposes of this paragraph, good cause shall exist only if publication of a term or provision of a settlement agreement would cause direct and substantial harm to any party."],[0,"(6) Restrictions on payment of attorneys' fees and expenses"],[1,"Total attorneys' fees and expenses awarded by the court to counsel for the plaintiff class shall not exceed a reasonable percentage of the amount of any damages and prejudgment interest actually paid to the class."],[0,"(7) Disclosure of settlement terms to class members"],[1,"Any proposed or final settlement agreement that is published or otherwise disseminated to the class shall include each of the following statements, along with a cover page summarizing the information contained in such statements:"],[0,"(A) Statement of plaintiff recovery"],[2,"The amount of the settlement proposed to be distributed to the parties to the action, determined in the aggregate and on an average per share basis."],[0,"(B) Statement of potential outcome of case"],[0,"(i) Agreement on amount of damages"],[3,"If the settling parties agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement concerning the average amount of such potential damages per share."],[0,"(ii) Disagreement on amount of damages"],[3,"If the parties do not agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement from each settling party concerning the issue or issues on which the parties disagree."],[0,"(iii) Inadmissibility for certain purposes"],[3,"A statement made in accordance with clause (i) or (ii) concerning the amount of damages shall not be admissible in any Federal or State judicial action or administrative proceeding, other than an action or proceeding arising out of such statement."],[0,"(C) Statement of attorneys' fees or costs sought"],[2,"If any of the settling parties or their counsel intend to apply to the court for an award of attorneys' fees or costs from any fund established as part of the settlement, a statement indicating which parties or counsel intend to make such an application, the amount of fees and costs that will be sought (including the amount of such fees and costs determined on an average per share basis), and a brief explanation supporting the fees and costs sought. Such information shall be clearly summarized on the cover page of any notice to a party of any proposed or final settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-4?type=usc&year=mostrecent&link-type=html"},"head":"§78u–4. Private securities litigation","tname":"Commerce and Trade","by":{"0":"19, 60","1":"32","3":"23"}},{"t":"usc","label":"26 U.S.C. § 1042","url":"https://www.law.cornell.edu/uscode/text/26/1042","by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/26/402","subs":["(e)(2)"],"by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 404","url":"https://www.law.cornell.edu/uscode/text/26/404","subs":["(a)(9)"],"by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 72","url":"https://www.law.cornell.edu/uscode/text/26/72","subs":["(t)(2)(A)(vi)"],"by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"4","1":"2"}},{"t":"usc","label":"29 U.S.C. § 1022","url":"https://www.law.cornell.edu/uscode/text/29/1022","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 1023","url":"https://www.law.cornell.edu/uscode/text/29/1023","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 1024","url":"https://www.law.cornell.edu/uscode/text/29/1024","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)","(a)(2)","(a)","(a)(1)(B)","(a)(1)(C)"],"stext":{"head":"§1104. Fiduciary duties","paras":[[0,"(a) Prudent man standard of care"],[0,"(1) Subject to sections 1103(c) and (d), 1342, and 1344 of this title, a fiduciary shall discharge his duties with respect to a plan solely in the interest of the participants and beneficiaries and—"],[1,"(A) for the exclusive purpose of:"],[2,"(i) providing benefits to participants and their beneficiaries; and"],[2,"(ii) defraying reasonable expenses of administering the plan;"],[1,"(B) with the care, skill, prudence, and diligence under the circumstances then prevailing that a prudent man acting in a like capacity and familiar with such matters would use in the conduct of an enterprise of a like character and with like aims;"],[1,"(C) by diversifying the investments of the plan so as to minimize the risk of large losses, unless under the circumstances it is clearly prudent not to do so; and"],[1,"(D) in accordance with the documents and instruments governing the plan insofar as such documents and instruments are consistent with the provisions of this subchapter and subchapter III."],[0,"(2) In the case of an eligible individual account plan (as defined in section 1107(d)(3) of this title), the diversification requirement of paragraph (1)(C) and the prudence requirement (only to the extent that it requires diversification) of paragraph (1)(B) is not violated by acquisition or holding of qualifying employer real property or qualifying employer securities (as defined in section 1107(d)(4) and (5) of this title)."],[0,"(b) Indicia of ownership of assets outside jurisdiction of district courts"],[0,"Except as authorized by the Secretary by regulations, no fiduciary may maintain the indicia of ownership of any assets of a plan outside the jurisdiction of the district courts of the United States."],[0,"(c) Control over assets by participant or beneficiary"],[0,"(1)(A) In the case of a pension plan which provides for individual accounts and permits a participant or beneficiary to exercise control over the assets in his account, if a participant or beneficiary exercises control over the assets in his account (as determined under regulations of the Secretary)—"],[1,"(i) such participant or beneficiary shall not be deemed to be a fiduciary by reason of such exercise, and"],[1,"(ii) no person who is otherwise a fiduciary shall be liable under this part for any loss, or by reason of any breach, which results from such participant's or beneficiary's exercise of control, except that this clause shall not apply in connection with such participant or beneficiary for any blackout period during which the ability of such participant or beneficiary to direct the investment of the assets in his or her account is suspended by a plan sponsor or fiduciary."],[0,"(B) If a person referred to in subparagraph (A)(ii) meets the requirements of this subchapter in connection with authorizing and implementing the blackout period, any person who is otherwise a fiduciary shall not be liable under this subchapter for any loss occurring during such period."],[0,"(C) For purposes of this paragraph, the term \"blackout period\" has the meaning given such term by section 1021(i)(7) of this title."],[0,"(2) In the case of a simple retirement account established pursuant to a qualified salary reduction arrangement under section 408(p) of title 26, a participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account upon the earliest of—"],[1,"(A) an affirmative election among investment options with respect to the initial investment of any contribution,"],[1,"(B) a rollover to any other simple retirement account or individual retirement plan, or"],[1,"(C) one year after the simple retirement account is established."],[0,"No reports, other than those required under section 1021(g) of this title, shall be required with respect to a simple retirement account established pursuant to such a qualified salary reduction arrangement."],[0,"(3) In the case of a pension plan which makes a transfer to an individual retirement account or annuity of a designated trustee or issuer under section 401(a)(31)(B) of title 26, the participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account or annuity upon—"],[1,"(A) the earlier of—"],[2,"(i) a rollover of all or a portion of the amount to another individual retirement account or annuity; or"],[2,"(ii) one year after the transfer is made; or"],[1,"(B) a transfer that is made in a manner consistent with guidance provided by the Secretary."],[0,"(4)(A) In any case in which a qualified change in investment options occurs in connection with an individual account plan, a participant or beneficiary shall not be treated for purposes of paragraph (1) as not exercising control over the assets in his account in connection with such change if the requirements of subparagraph (C) are met in connection with such change."],[0,"(B) For purposes of subparagraph (A), the term \"qualified change in investment options\" means, in connection with an individual account plan, a change in the investment options offered to the participant or beneficiary under the terms of the plan, under which—"],[1,"(i) the account of the participant or beneficiary is reallocated among one or more remaining or new investment options which are offered in lieu of one or more investment options offered immediately prior to the effective date of the change, and"],[1,"(ii) the stated characteristics of the remaining or new investment options provided under clause (i), including characteristics relating to risk and rate of return, are, as of immediately after the change, reasonably similar to those of the existing investment options as of immediately before the change."],[0,"(C) The requirements of this subparagraph are met in connection with a qualified change in investment options if—"],[1,"(i) at least 30 days and no more than 60 days prior to the effective date of the change, the plan administrator furnishes written notice of the change to the participants and beneficiaries, including information comparing the existing and new investment options and an explanation that, in the absence of affirmative investment instructions from the participant or beneficiary to the contrary, the account of the participant or beneficiary will be invested in the manner described in subparagraph (B),"],[1,"(ii) the participant or beneficiary has not provided to the plan administrator, in advance of the effective date of the change, affirmative investment instructions contrary to the change, and"],[1,"(iii) the investments under the plan of the participant or beneficiary as in effect immediately prior to the effective date of the change were the product of the exercise by such participant or beneficiary of control over the assets of the account within the meaning of paragraph (1)."],[0,"(5) Default investment arrangements.—"],[1,"(A) In general.—For purposes of paragraph (1), a participant or beneficiary in an individual account plan meeting the notice requirements of subparagraph (B) shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which, in the absence of an investment election by the participant or beneficiary, are invested by the plan in accordance with regulations prescribed by the Secretary. The regulations under this subparagraph shall provide guidance on the appropriateness of designating default investments that include a mix of asset classes consistent with capital preservation or long-term capital appreciation, or a blend of both."],[1,"(B) Notice requirements.—"],[2,"(i) In general.—The requirements of this subparagraph are met if each participant or beneficiary—"],[3,"(I) receives, within a reasonable period of time before each plan year, a notice explaining the employee's right under the plan to designate how contributions and earnings will be invested and explaining how, in the absence of any investment election by the participant or beneficiary, such contributions and earnings will be invested, and"],[3,"(II) has a reasonable period of time after receipt of such notice and before the beginning of the plan year to make such designation."],[2,"(ii) Form of notice.—The requirements of clauses (i) and (ii) of section 401(k)(12)(D) of title 26 shall apply with respect to the notices described in this subparagraph."],[0,"(6) Default investment arrangements for a pension-linked emergency savings account.—For purposes of paragraph (1), a participant in a pension-linked emergency savings account shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which are invested in accordance with section 1193(c)(1)(A)(iii) of this title."],[0,"(d) Plan terminations"],[0,"(1) If, in connection with the termination of a pension plan which is a single-employer plan, there is an election to establish or maintain a qualified replacement plan, or to increase benefits, as provided under section 4980(d) of title 26, a fiduciary shall discharge the fiduciary's duties under this subchapter and subchapter III in accordance with the following requirements:"],[1,"(A) In the case of a fiduciary of the terminated plan, any requirement—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1104?type=usc&year=mostrecent&link-type=html"},"head":"§1104. Fiduciary duties","tname":"Labor","by":{"0":"passim, 5","1":"23, 2, 2, 3, 14, 30, 3, 4","2":"37, 20, 5, 40, 45, 1","3":"4, 17"}},{"t":"usc","label":"29 U.S.C. § 1107","url":"https://www.law.cornell.edu/uscode/text/29/1107","subs":["(b)(1)","(d)(6)","(d)(3)(A)(ii)","(d)(5)","(d)(6)(A)"],"stext":{"head":"§1107. Limitation with respect to acquisition and holding of employer securities and employer real property by certain plans","paras":[[0,"(a) Percentage limitation"],[0,"Except as otherwise provided in this section and section 1114 of this title:"],[1,"(1) A plan may not acquire or hold—"],[2,"(A) any employer security which is not a qualifying employer security, or"],[2,"(B) any employer real property which is not qualifying employer real property."],[1,"(2) A plan may not acquire any qualifying employer security or qualifying employer real property, if immediately after such acquisition the aggregate fair market value of employer securities and employer real property held by the plan exceeds 10 percent of the fair market value of the assets of the plan."],[1,"(3)(A) After December 31, 1984, a plan may not hold any qualifying employer securities or qualifying employer real property (or both) to the extent that the aggregate fair market value of such securities and property determined on December 31, 1984, exceeds 10 percent of the greater of—"],[2,"(i) the fair market value of the assets of the plan, determined on December 31, 1984, or"],[2,"(ii) the fair market value of the assets of the plan determined on January 1, 1975."],[1,"(B) Subparagraph (A) of this paragraph shall not apply to any plan which on any date after December 31, 1974; and before January 1, 1985, did not hold employer securities or employer real property (or both) the aggregate fair market value of which determined on such date exceeded 10 percent of the greater of 1"],[2,"(i) the fair market value of the assets of the plan, determined on such date, or"],[2,"(ii) the fair market value of the assets of the plan determined on January 1, 1975."],[1,"(4)(A) After December 31, 1979, a plan may not hold any employer securities or employer real property in excess of the amount specified in regulations under subparagraph (B). This subparagraph shall not apply to a plan after the earliest date after December 31, 1974, on which it complies with such regulations."],[1,"(B) Not later than December 31, 1976, the Secretary shall prescribe regulations which shall have the effect of requiring that a plan divest itself of 50 percent of the holdings of employer securities and employer real property which the plan would be required to divest before January 1, 1985, under paragraph (2) or subsection (c) (whichever is applicable)."],[0,"(b) Exception"],[0,"(1) Subsection (a) of this section shall not apply to any acquisition or holding of qualifying employer securities or qualifying employer real property by an eligible individual account plan."],[0,"(2)(A) If this paragraph applies to an eligible individual account plan, the portion of such plan which consists of applicable elective deferrals (and earnings allocable thereto) shall be treated as a separate plan—"],[1,"(i) which is not an eligible individual account plan, and"],[1,"(ii) to which the requirements of this section apply."],[0,"(B)(i) This paragraph shall apply to any eligible individual account plan if any portion of the plan's applicable elective deferrals (or earnings allocable thereto) are required to be invested in qualifying employer securities or qualifying employer real property or both—"],[1,"(I) pursuant to the terms of the plan, or"],[1,"(II) at the direction of a person other than the participant on whose behalf such elective deferrals are made to the plan (or a beneficiary)."],[0,"(ii) This paragraph shall not apply to an individual account plan for a plan year if, on the last day of the preceding plan year, the fair market value of the assets of all individual account plans maintained by the employer equals not more than 10 percent of the fair market value of the assets of all pension plans (other than multiemployer plans) maintained by the employer."],[0,"(iii) This paragraph shall not apply to an individual account plan that is an employee stock ownership plan as defined in section 4975(e)(7) of title 26."],[0,"(iv) This paragraph shall not apply to an individual account plan if, pursuant to the terms of the plan, the portion of any employee's applicable elective deferrals which is required to be invested in qualifying employer securities and qualifying employer real property for any year may not exceed 1 percent of the employee's compensation which is taken into account under the plan in determining the maximum amount of the employee's applicable elective deferrals for such year."],[0,"(C) For purposes of this paragraph, the term \"applicable elective deferral\" means any elective deferral (as defined in section 402(g)(3)(A) of title 26) which is made pursuant to a qualified cash or deferred arrangement as defined in section 401(k) of title 26."],[0,"(3) Cross References.—"],[2,"(A) For exemption from diversification requirements for holding of qualifying employer securities and qualifying employer real property by eligible individual account plans, see section 1104(a)(2) of this title."],[2,"(B) For exemption from prohibited transactions for certain acquisitions of qualifying employer securities and qualifying employer real property which are not in violation of 10 percent limitation, see section 1108(e) of this title."],[2,"(C) For transitional rules respecting securities or real property subject to binding contracts in effect on June 30, 1974, see section 1114(c) of this title."],[2,"(D) For diversification requirements for qualifying employer securities held in certain individual account plans, see section 1054(j) of this title."],[0,"(c) Election"],[0,"(1) A plan which makes the election, under paragraph (3) shall be treated as satisfying the requirement of subsection (a)(3) if and only if employer securities held on any date after December 31, 1974 and before January 1, 1985 have a fair market value, determined as of December 31, 1974, not in excess of 10 percent of the lesser of—"],[1,"(A) the fair market value of the assets of the plan determined on such date (disregarding any portion of the fair market value of employer securities which is attributable to appreciation of such securities after December 31, 1974) but not less than the fair market value of plan assets on January 1, 1975, or"],[1,"(B) an amount equal to the sum of (i) the total amount of the contributions to the plan received after December 31, 1974, and prior to such date, plus (ii) the fair market value of the assets of the plan, determined on January 1, 1975."],[0,"(2) For purposes of this subsection, in the case of an employer security held by a plan after January 1, 1975, the ownership of which is derived from ownership of employer securities held by the plan on January 1, 1975, or from the exercise of rights derived from such ownership, the value of such security held after January 1, 1975, shall be based on the value as of January 1, 1975, of the security from which ownership was derived. The Secretary shall prescribe regulations to carry out this paragraph."],[0,"(3) An election under this paragraph may not be made after December 31, 1975. Such an election shall be made in accordance with regulations prescribed by the Secretary, and shall be irrevocable. A plan may make an election under this paragraph only if on January 1, 1975, the plan holds no employer real property. After such election and before January 1, 1985 the plan may not acquire any employer real property."],[0,"(d) Definitions"],[0,"For purposes of this section—"],[1,"(1) The term \"employer security\" means a security issued by an employer of employees covered by the plan, or by an affiliate of such employer. A contract to which section 1108(b)(5) of this title applies shall not be treated as a security for purposes of this section."],[1,"(2) The term \"employer real property\" means real property (and related personal property) which is leased to an employer of employees covered by the plan, or to an affiliate of such employer. For purposes of determining the time at which a plan acquires employer real property for purposes of this section, such property shall be deemed to be acquired by the plan on the date on which the plan acquires the property or on the date on which the lease to the employer (or affiliate) is entered into, whichever is later."],[1,"(3)(A) The term \"eligible individual account plan\" means an individual account plan which is (i) a profit-sharing, stock bonus, thrift, or savings plan; (ii) an employee stock ownership plan; or (iii) a money purchase plan which was in existence on September 2, 1974, and which on such date invested primarily in qualifying employer securities. Such term excludes an individual retirement account or annuity described in section 408 of title 26."],[1,"(B) Notwithstanding subparagraph (A), a plan shall be treated as an eligible individual account plan with respect to the acquisition or holding of qualifying employer real property or qualifying employer securities only if such plan explicitly provides for acquisition and holding of qualifying employer securities or qualifying employer real property (as the case may be). In the case of a plan in existence on September 2, 1974, this subparagraph shall not take effect until January 1, 1976."],[1,"(C) The term \"eligible individual account plan\" does not include any individual account plan the benefits of which are taken into account in determining the benefits payable to a participant under any defined benefit plan."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1107?type=usc&year=mostrecent&link-type=html"},"head":"§1107. Limitation with respect to acquisition and holding of employer securities and employer real property by certain plans","tname":"Labor","by":{"0":"5, 5","1":"3, 3, 3"}},{"t":"usc","label":"29 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/29/1108","subs":["(c)(3)"],"stext":{"head":"§1108. Exemptions from prohibited transactions","paras":[[0,"(a) Grant of exemptions"],[0,"The Secretary shall establish an exemption procedure for purposes of this subsection. Pursuant to such procedure, he may grant a conditional or unconditional exemption of any fiduciary or transaction, or class of fiduciaries or transactions, from all or part of the restrictions imposed by sections 1106 and 1107(a) of this title. Action under this subsection may be taken only after consultation and coordination with the Secretary of the Treasury. An exemption granted under this section shall not relieve a fiduciary from any other applicable provision of this chapter. The Secretary may not grant an exemption under this subsection unless he finds that such exemption is—"],[1,"(1) administratively feasible,"],[1,"(2) in the interests of the plan and of its participants and beneficiaries, and"],[1,"(3) protective of the rights of participants and beneficiaries of such plan."],[0,"Before granting an exemption under this subsection from section 1106(a) or 1107(a) of this title, the Secretary shall publish notice in the Federal Register of the pendency of the exemption, shall require that adequate notice be given to interested persons, and shall afford interested persons opportunity to present views. The Secretary may not grant an exemption under this subsection from section 1106(b) of this title unless he affords an opportunity for a hearing and makes a determination on the record with respect to the findings required by paragraphs (1), (2), and (3) of this subsection."],[0,"(b) Enumeration of transactions exempted from section 1106 prohibitions"],[0,"The prohibitions provided in section 1106 of this title shall not apply to any of the following transactions:"],[1,"(1) Any loans made by the plan to parties in interest who are participants or beneficiaries of the plan if such loans (A) are available to all such participants and beneficiaries on a reasonably equivalent basis, (B) are not made available to highly compensated employees (within the meaning of section 414(q) of title 26) in an amount greater than the amount made available to other employees, (C) are made in accordance with specific provisions regarding such loans set forth in the plan, (D) bear a reasonable rate of interest, and (E) are adequately secured. A loan made by a plan shall not fail to meet the requirements of the preceding sentence by reason of a loan repayment suspension described under section 414(u)(4) of title 26."],[1,"(2)(A) Contracting or making reasonable arrangements with a party in interest for office space, or legal, accounting, or other services necessary for the establishment or operation of the plan, if no more than reasonable compensation is paid therefor."],[1,"(B)(i) No contract or arrangement for services between a covered plan and a covered service provider, and no extension or renewal of such a contract or arrangement, is reasonable within the meaning of this paragraph unless the requirements of this clause 1 are met."],[1,"(ii)(I) For purposes of this subparagraph:"],[2,"(aa) The term \"covered plan\" means a group health plan as defined section 2 1191b(a) of this title."],[2,"(bb) The term \"covered service provider\" means a service provider that enters into a contract or arrangement with the covered plan and reasonably expects $1,000 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or more in compensation, direct or indirect, to be received in connection with providing one or more of the following services, pursuant to the contract or arrangement, regardless of whether such services will be performed, or such compensation received, by the covered service provider, an affiliate, or a subcontractor:"],[3,"(AA) Brokerage services, for which the covered service provider, an affiliate, or a subcontractor reasonably expects to receive indirect compensation or direct compensation described in item (dd), provided to a covered plan with respect to selection of insurance products (including vision and dental), recordkeeping services, medical management vendor, benefits administration (including vision and dental), stop-loss insurance, pharmacy benefit management services, wellness services, transparency tools and vendors, group purchasing organization preferred vendor panels, disease management vendors and products, compliance services, employee assistance programs, or third party administration services."],[3,"(BB) Consulting, for which the covered service provider, an affiliate, or a subcontractor reasonably expects to receive indirect compensation or direct compensation described in item (dd), related to the development or implementation of plan design, insurance or insurance product selection (including vision and dental), recordkeeping, medical management, benefits administration selection (including vision and dental), stop-loss insurance, pharmacy benefit management services, wellness design and management services, transparency tools, group purchasing organization agreements and services, participation in and services from preferred vendor panels, disease management, compliance services, employee assistance programs, or third party administration services."],[2,"(cc) The term \"affiliate\", with respect to a covered service provider, means an entity that directly or indirectly (through one or more intermediaries) controls, is controlled by, or is under common control with, such provider, or is an officer, director, or employee of, or partner in, such provider."],[2,"(dd)(AA) The term \"compensation\" means anything of monetary value, but does not include non-monetary compensation valued at $250 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or less, in the aggregate, during the term of the contract or arrangement."],[2,"(BB) The term \"direct compensation\" means compensation received directly from a covered plan."],[2,"(CC) The term \"indirect compensation\" means compensation received from any source other than the covered plan, the plan sponsor, the covered service provider, or an affiliate. Compensation received from a subcontractor is indirect compensation, unless it is received in connection with services performed under a contract or arrangement with a subcontractor."],[2,"(ee) The term \"responsible plan fiduciary\" means a fiduciary with authority to cause the covered plan to enter into, or extend or renew, the contract or arrangement."],[2,"(ff) The term \"subcontractor\" means any person or entity (or an affiliate of such person or entity) that is not an affiliate of the covered service provider and that, pursuant to a contract or arrangement with the covered service provider or an affiliate, reasonably expects to receive $1,000 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or more in compensation for performing one or more services described in item (bb) under a contract or arrangement with the covered plan."],[1,"(II) For purposes of this subparagraph, a description of compensation or cost may be expressed as a monetary amount, formula, or a per capita charge for each enrollee or, if the compensation or cost cannot reasonably be expressed in such terms, by any other reasonable method, including a disclosure that additional compensation may be earned but may not be calculated at the time of contract if such a disclosure includes a description of the circumstances under which the additional compensation may be earned and a reasonable and good faith estimate if the covered service provider cannot otherwise readily describe compensation or cost and explains the methodology and assumptions used to prepare such estimate. Any such description shall contain sufficient information to permit evaluation of the reasonableness of the compensation or cost."],[1,"(III) No person or entity is a \"covered service provider\" within the meaning of subclause (I)(bb) solely on the basis of providing services as an affiliate or a subcontractor that is performing one or more of the services described in subitem (AA) or (BB) of such subclause under the contract or arrangement with the covered plan."],[1,"(iii) A covered service provider shall disclose to a responsible plan fiduciary, in writing, the following:"],[2,"(I) A description of the services to be provided to the covered plan pursuant to the contract or arrangement."],[2,"(II) If applicable, a statement that the covered service provider, an affiliate, or a subcontractor will provide, or reasonably expects to provide, services pursuant to the contract or arrangement directly to the covered plan as a fiduciary (within the meaning of section 1002(21) of this title)."],[2,"(III) A description of all direct compensation, either in the aggregate or by service, that the covered service provider, an affiliate, or a subcontractor reasonably expects to receive in connection with the services described in subclause (I)."],[2,"(IV)(aa) A description of all indirect compensation that the covered service provider, an affiliate, or a subcontractor reasonably expects to receive in connection with the services described in subclause (I)—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1108?type=usc&year=mostrecent&link-type=html"},"head":"§1108. Exemptions from prohibited transactions","tname":"Labor","by":{"0":"8, 23, 32, 58","1":"16","3":"3"}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"by":{"0":"5, 35"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(2)","(a)(3)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"5","1":"3, 3"}},{"t":"law","label":"Pub. L. No. 94-455","url":"https://www.govinfo.gov/link/statute/90/1521","by":{"0":"6, 46, 57"}},{"t":"reg","label":"17 C.F.R. § 240.13a-1","url":"https://www.ecfr.gov/current/title-17/section-240.13a-1","by":{"0":"29"}},{"t":"reg","label":"17 C.F.R. § 240.13a-11","url":"https://www.ecfr.gov/current/title-17/section-240.13a-11","by":{"0":"29"}},{"t":"reg","label":"17 C.F.R. § 240.13a-13","url":"https://www.ecfr.gov/current/title-17/section-240.13a-13","by":{"0":"29"}},{"t":"reg","label":"17 C.F.R. § 249.308","url":"https://www.ecfr.gov/current/title-17/section-249.308","by":{"0":"29"}},{"t":"reg","label":"17 C.F.R. § 249.308a","url":"https://www.ecfr.gov/current/title-17/section-249.308a","by":{"0":"29"}},{"t":"reg","label":"17 C.F.R. § 249.310","url":"https://www.ecfr.gov/current/title-17/section-249.310","by":{"0":"29"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"5","2":"15, 17, 23, 30, 46"}},{"t":"case","label":"Backman v. Polaroid Corp.","cite":"910 F.2d 10","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/910/10/","by":{"1":"19"}},{"t":"case","label":"Basic Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"sum":"The Supreme Court held that there was no reason to artificially exclude merger conversations from the definition of materiality simply because they do not include specific prices.","sumSrc":"Oyez","by":{"1":"19, 26","2":"48"}},{"t":"case","label":"Bateman Eichler, Hill Richards, Inc. v. Berner","cite":"472 U.S. 299","y":1985,"id":"1984/84-679","sc":1,"sum":"There is no basis at this stage of the litigation for applying the in pari delicto defense to bar respondents' action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Bell Atl. Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"1":"5","2":"passim"}},{"t":"case","label":"Central States, Se. & Sw. Areas Pension Fund v. Central Transp., Inc.","cite":"472 U.S. 559","y":1985,"id":"1984/82-2157","sc":1,"ar":1,"sum":"Respondents must allow petitioners to conduct the requested audit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"21, 23"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 22"}},{"t":"case","label":"Higginbotham v. Baxter Int’l Inc.","cite":"495 F.3d 753","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/495/753/","by":{"1":"21","2":"58"}},{"t":"case","label":"Kokesh v. SEC","cite":"137 S. Ct. 1635","y":2017,"id":"2016/16-529","sc":1,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Lorenzo v. SEC","cite":"139 S. Ct. 1094","y":2019,"id":"2018/17-1077","sc":1,"sum":"Dissemination of false or misleading statements with intent to defraud can fall within the scope of SEC Rules 10b–5(a) and (c), as well as the relevant statutory provisions, even if the disseminator cannot be held liable under Rule 10b–5(b).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"sum":"The Court held that a plaintiff could state a claim based on a pharmaceutical company's non-disclosure of adverse event reports, even though the reports are not alleged to be statistically significant.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"NLRB v. Amax Coal Co.","cite":"453 U.S. 322","y":1981,"id":"1980/80-289","sc":1,"sum":"Employer-selected trustees of a § 302 (c) (5) trust fund are not \"representatives\" of the employer \"for the purposes of collective bargaining or the adjustment of grievances\" within the meaning of § 8 (b) (1) (B). Pp. 328-338. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"SEC v. Materia","cite":"745 F.2d 197","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/745/197/","by":{"1":"20"}},{"t":"case","label":"United States v. Newman","cite":"664 F.2d 12","y":1981,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/664/12/","by":{"1":"20"}},{"t":"law","label":"Pub. L. No. 93-406","url":"https://www.govinfo.gov/link/statute/88/829","by":{"1":"1"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(21)(a)","(34)"],"by":{"1":"2, 3"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","subs":["(i)"],"by":{"1":"17"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"usc","label":"29 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/29/1103","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"29 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/29/1105","subs":["(a)","(a)(3)"],"by":{"1":"23, 24, 23"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"1":"10"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"1":"15"}},{"t":"usc","label":"15 U.S.C. § 78j-1","url":"https://www.law.cornell.edu/uscode/text/15/78j-1","subs":["(b)"],"by":{"1":"21"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(d)"],"by":{"1":"19"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","by":{"1":"23"}},{"t":"usc","label":"15 U.S.C. § 7245","url":"https://www.law.cornell.edu/uscode/text/15/7245","by":{"1":"21"}},{"t":"usc","label":"18 U.S.C. § 1514A","url":"https://www.law.cornell.edu/uscode/text/18/1514A","by":{"1":"23"}},{"t":"case","label":"Bethune-Hill v. Va. State Bd. of Elections","cite":"137 S. Ct. 788","y":2017,"id":"2016/15-680","sc":1,"sum":"The Court determined that race can be shown to be the predominant factor in redistricting even when traditional principles are respected, and that district courts must engage in a holistic analysis.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Braden v. Wal-Mart Stores, Inc.","cite":"588 F.3d 585","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/588/585/","sum":"Holding that a court evaluating a breach of fiduciary duty claim must conduct a “careful and holistic evaluation of an ERISA complaint’s factual allegations”.","sumSrc":"brief:2","by":{"2":"44"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"60"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"op":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. R.R.","cite":"135 S. Ct. 1225","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1225/","sc":1,"by":{"2":"37"}},{"t":"case","label":"Donovan v. Bierwirth","cite":"680 F.2d 263","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/680/263/","by":{"2":"61"}},{"t":"case","label":"Fentress v. Exxon Mobil Corp.","cite":"2019 U.S. Dist. LEXIS 16934","y":2019,"court":"S.D. Tex. Feb. 4","by":{"2":"35"}},{"t":"case","label":"Forte v. U.S. Pension Committee","cite":"2016 WL 5922653","y":2016,"court":"S.D.N.Y. Sept. 30","by":{"2":"53"}},{"t":"case","label":"Fry v. Napoleon Cmty. Sch.","cite":"137 S. Ct. 743","y":2017,"id":"2016/15-497","sc":1,"sum":"The Court determined that the Individuals with Disabilities Education Act’s requirement that plaintiffs exhaust administrative remedies before suing under the Americans with Disabilities Act and the Rehabilitation Act only applies to individuals seeking relief for the denial of a free and appropriate public education.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Graham v. Fearon","cite":"721 F. App’x 419","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/721/419/","by":{"2":"passim"}},{"t":"case","label":"Gray v. Citigroup Inc. (In re Citigroup ERISA Litig.)","cite":"662 F.3d 128","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/662/128/","by":{"2":"13"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"op":8,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"16, 17","3":"22"}},{"t":"case","label":"Harris v. Amgen Inc.","cite":"788 F.3d 916","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/916/","by":{"2":"21, 24"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"2":"60"}},{"t":"case","label":"Knight v. Comm’r","cite":"552 U.S. 181","y":2008,"id":"2007/06-1286","sc":1,"sum":"Roberts reasoned that the tax statute at issue required a court to decide whether an individual customarily would spend money on the type of service at issue; if so, the expense would not be fully deductible by a trust. The case was remanded for further proceedings.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Kuper v. Iovenko","cite":"66 F.3d 1447","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/66/1447/","by":{"2":"13"}},{"t":"case","label":"Moench v. Robertson","cite":"62 F.3d 553","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/62/553/","ar":3,"by":{"2":"13, 14, 18, 24, 35"}},{"t":"case","label":"O’Day v. Chatila","cite":"2019 U.S. App. LEXIS 17199","y":2019,"court":"2d Cir. June 7","by":{"2":"34, 35"}},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"op":8,"sum":"The Court held that it is the duty of the court system to harmonize statutes, and that barring one applicable statute by use of another represents a disregard of the law's intent of having cooperative statutes.","sumSrc":"Oyez","by":{"2":"61"}},{"t":"case","label":"Peoria Union Stock Yards Co. v. Penn. Mut. Life Ins. Co.","cite":"698 F.3d 320","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/320/","by":{"2":"54"}},{"t":"case","label":"Quan v. Comput. Scis. Corp.","cite":"623 F.3d 870","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/623/870/","by":{"2":"13"}},{"t":"case","label":"Scheuer v. Rhodes","cite":"416 U.S. 232","y":1974,"id":"1973/72-914","sc":1,"sum":"Petitioners, the personal representatives of the estates of students who were killed on the campus of*a state-controlled university, brought these damages actions under 42 U. S. C. § 1983 against the Governor, the Adjutant General of the Ohio National Guard, various other Guard officers and enlisted members, and the university president, charging that those officials, acting under color of state law, \"intentionally, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"White v. Marshall & Ilsley Corp.","cite":"714 F.3d 980","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/714/980/","by":{"2":"13"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(d)"],"by":{"2":"17, 39"}},{"t":"case","label":"OTHER AUTHORITIES Oral Argument at 33:09, Jander v. Ret. Plans Comm. of IBM","cite":"910 F.3d 620","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/910/620/","op":1,"by":{"2":"51"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"ar":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19, 23"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"sum":"The Court held that Jones was not entitled to an instruction as to the effect of jury deadlock. The Court held that the Eighth Amendment does not require such an instruction and the Court declined to exercise its supervisory powers to require such an instruction in every capital case.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"O’Day v. Chatila","cite":"774 F. App’x 708","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/774/708/","by":{"3":"20"}},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"sum":"After establishing its federal jurisdiction, despite a claim that the matter involved aspects of Ohio's Constitution, the Court held that when looking at the totality of the circumstances it may be reasonably concluded that if a defendant consents to be searched, even if not first advised that he is \"free to go,\" the ensuing search will be recognized as voluntary.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Richlin Sec. Serv. Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"sum":"The Court held that such paralegal fees are recoverable at market rates. Justice Samuel A. Alito stated that because Richlin incurred fees for paralegal services in connection with its case, a straightforward reading of the statute demonstrates that Richlin was entitled to recover fees for the paralegal services it purchased at the market rate.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"United States v. Grubbs","cite":"547 U.S. 90","y":2006,"id":"2005/04-1414","sc":1,"sum":"Justice Antonin Scalia, in the majority opinion, wrote that under the Fourth Amendment's particularity requirement a warrant need not set out the conditions that trigger it, only the place to be searched and the persons or things to be searched for. The fact that the triggering conditions were included in the affidavit, even if they were never showed to Grubbs, was therefore sufficient.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}}]};